files.game.js:
const cv = document.getElementById('game');
const ctx = cv.getContext('2d');
const GAP = 130, PW = 70, BX = cv.width / 2, R = 13;
let bird = { y: 220, v: 0 };
let pipes = [], tick = 0, score = 0, over = false;

function flap() {
  if (over) {
    bird = { y: 220, v: 0 };
    pipes = []; score = 0; over = false;
    return;
  }
  bird.v = -5.5;
}

function spawn() {
  const y = 60 + Math.random() * (cv.height - 200);
  pipes.push({ x: cv.width, y: y, pass: false });
}

addEventListener('keydown', e => {
  if (e.code === 'Space') { e.preventDefault(); flap(); }
});
cv.onclick = flap;

function step() {
  bird.v += 0.35;
  bird.y += bird.v;
  tick++;
  if (tick % 90 === 0) spawn();
  for (const p of pipes) p.x -= 2.4;
  pipes = pipes.filter(p => p.x > -PW);
  for (const p of pipes) {
    if (BX > p.x && BX < p.x + PW && !p.pass) { p.pass = true; score++; }
    const inX = BX + R > p.x && BX - R < p.x + PW;
    if (inX && (bird.y - R < p.y || bird.y + R > p.y + GAP)) over = true;
  }
  if (bird.y > cv.height - R || bird.y < -R) over = true;
}

function draw() {
  ctx.fillStyle = '#101828';
  ctx.fillRect(0, 0, cv.width, cv.height);
  ctx.fillStyle = '#3edc81';
  for (const p of pipes) {
    ctx.fillRect(p.x, 0, PW, p.y);
    ctx.fillRect(p.x, p.y + GAP, PW, cv.height);
  }
  ctx.fillStyle = '#ffd23f';
  ctx.beginPath();
  ctx.arc(BX, bird.y, R, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = '#ffffff';
  ctx.font = '20px system-ui';
  ctx.fillText('Score: ' + score, 14, 28);
  if (over) ctx.fillText('Game over — click to restart', cv.width / 2 - 132, cv.height / 2);
}

setInterval(() => {
  if (!over) step();
  draw();
}, 1000 / 60);
